<script lang="ts">
	import { onMount } from 'svelte';
	import { goto } from '$app/navigation';
	import { api, ApiError } from '$lib/api';
	import { workspace } from '$lib/workspace.svelte';
	import { Badge, Button, Card, CardContent, CardDescription, CardHeader, CardTitle, Input } from '$lib/components/ui';
	import { BrainCircuit, ChevronRight, CircleCheck, FileText, Folder, FolderTree, Plus, RotateCcw, Save, Search, Trash2 } from '@lucide/svelte';

	type Entry={name:string;type:'dir'|'file';system?:boolean};
	type TreeNode={name:string;path:string;type:'folder'|'file';children?:TreeNode[]};
	type CoreItem={id:string;path:string;itemType:'folder'|'file';group:string;projectId?:string;role:'load-first'|'always'|'active'|'relevant'|'requested'|'search';state:'active'|'final'|'superseded'|'archive';protection:'editable'|'permission'|'locked'};
	type ProjectRoute={id:string;label:string;destination:string;routing:'automatic'|'suggest'|'manual'};
	type ProjectSetup={id:string;name:string;rootPath:string;contextRole:'active'|'relevant'|'requested';routes:ProjectRoute[]};

	let started=$state(false),scanning=$state(false),saving=$state(false),step=$state(1),error=$state(''),notice=$state('');
	let targetWorkspaceId=$state(''),savedRevision=$state(0);
	let tree:TreeNode[]=$state([]),coreItems:CoreItem[]=$state([]),projectSetups:ProjectSetup[]=$state([]);
	let selectedCorePaths:string[]=$state([]),coreSearch=$state(''),globalGroup=$state('Global Core Files');
	let selectedProjectPaths:string[]=$state([]),projectSearch=$state(''),projectGroup=$state('Active / Relevant Content'),selectedProjectId=$state('');
	let newProject=$state({name:'',rootPath:'',contextRole:'relevant' as ProjectSetup['contextRole']});
	let routeDrafts=$state<Record<string,{label:string;destination:string;routing:ProjectRoute['routing']}>>({});

	async function walk(subpath='',depth=0):Promise<TreeNode[]>{
		if(depth>6)return[];
		const r=await api.get<{entries:Entry[]}>(`/files?subpath=${encodeURIComponent(subpath)}`);
		const out:TreeNode[]=[];
		for(const e of (r.entries||[]).filter((item)=>!item.system)){
			const path=subpath?`${subpath}/${e.name}`:e.name;
			const node:TreeNode={name:e.name,path,type:e.type==='dir'?'folder':'file'};
			if(e.type==='dir')node.children=await walk(path,depth+1);
			out.push(node);
			if(out.length>300)break;
		}
		return out;
	}
	function flatten(nodes:TreeNode[]):TreeNode[]{return nodes.flatMap((node)=>[node,...flatten(node.children||[])]);}
	const flat=$derived(flatten(tree));
	function currentWorkspaceId(){return targetWorkspaceId||workspace.currentId||workspace.current?.id||'';}
	function messageFor(err:unknown,fallback:string){return err instanceof ApiError?err.message:err instanceof Error?err.message:fallback;}

	async function loadSaved(){
		const id=currentWorkspaceId();if(!id)return;
		try{
			const result=await api.get<any>(`/workspaces/${encodeURIComponent(id)}/knowledge-architecture`);
			const architecture=result.architecture;
			if(architecture?.setupComplete){
				coreItems=[...(architecture.globalItems||[]),...(architecture.projectItems||[])];
				projectSetups=architecture.projects||[];
				routeDrafts=Object.fromEntries(projectSetups.map((project)=>[project.id,{label:'',destination:'',routing:'automatic' as const}]));
				savedRevision=Number(architecture.revision||0);started=true;step=5;
			}
		}catch(err){error=messageFor(err,'Could not load Knowledge Setup');}
	}
	async function scan(){scanning=true;error='';notice='';try{tree=await walk();started=true;step=2;}catch(err){error=messageFor(err,'Workspace scan failed');}finally{scanning=false;}}
	async function saveArchitecture(){
		const id=currentWorkspaceId();if(!id)return;saving=true;error='';notice='';
		try{
			const result=await api.put<any>(`/workspaces/${encodeURIComponent(id)}/knowledge-architecture`,{setupComplete:true,items:coreItems,projects:projectSetups});
			savedRevision=Number(result.architecture?.revision||savedRevision+1);
			const sync=result.librarySync||{};
			notice=`Knowledge Setup saved · revision ${savedRevision} · Library ${Number(sync.synced||0)} added / ${Number(sync.existing||0)} already registered`;
			step=5;
		}catch(err){error=messageFor(err,'Could not save Knowledge Setup');}finally{saving=false;}
	}
	function reset(){started=false;step=1;tree=[];coreItems=[];projectSetups=[];selectedCorePaths=[];selectedProjectPaths=[];selectedProjectId='';error='';notice='';}
	function descendantPaths(path:string){const node=flat.find((item)=>item.path===path);if(!node)return[path];return node.type==='folder'?flat.filter((item)=>item.path===path||item.path.startsWith(`${path}/`)).map((item)=>item.path):[path];}
	function toggleCore(path:string,checked:boolean){const affected=descendantPaths(path);selectedCorePaths=checked?[...new Set([...selectedCorePaths,...affected])]:selectedCorePaths.filter((item)=>!affected.includes(item));}
	function addSelectedCore(){
		const existing=new Set(coreItems.map((item)=>item.path));
		const next=selectedCorePaths.filter((path)=>!existing.has(path)).map((path)=>{const node=flat.find((item)=>item.path===path);return{id:crypto.randomUUID(),path,itemType:node?.type||'file',group:globalGroup,role:'load-first' as const,state:'active' as const,protection:'permission' as const};});
		coreItems=[...coreItems,...next];selectedCorePaths=[];
	}
	function addProject(){
		if(!newProject.name.trim()||!newProject.rootPath)return;
		const id=crypto.randomUUID();projectSetups=[...projectSetups,{id,name:newProject.name.trim(),rootPath:newProject.rootPath,contextRole:newProject.contextRole,routes:[]}];
		routeDrafts={...routeDrafts,[id]:{label:'',destination:'',routing:'automatic'}};newProject={name:'',rootPath:'',contextRole:'relevant'};
	}
	function addProjectRoute(projectId:string){const draft=routeDrafts[projectId];if(!draft?.label.trim()||!draft.destination)return;projectSetups=projectSetups.map((project)=>project.id===projectId?{...project,routes:[...project.routes,{id:crypto.randomUUID(),label:draft.label.trim(),destination:draft.destination,routing:draft.routing}]}:project);routeDrafts={...routeDrafts,[projectId]:{label:'',destination:'',routing:'automatic'}};}
	function toggleProjectPath(path:string,checked:boolean){const affected=descendantPaths(path);selectedProjectPaths=checked?[...new Set([...selectedProjectPaths,...affected])]:selectedProjectPaths.filter((item)=>!affected.includes(item));}
	function addSelectedProjectItems(){if(!selectedProjectId)return;const existing=new Set(coreItems.filter((item)=>item.projectId===selectedProjectId).map((item)=>item.path));const next=selectedProjectPaths.filter((path)=>!existing.has(path)).map((path)=>{const node=flat.find((item)=>item.path===path);return{id:crypto.randomUUID(),path,itemType:node?.type||'file',group:projectGroup,projectId:selectedProjectId,role:'relevant' as const,state:'active' as const,protection:'permission' as const};});coreItems=[...coreItems,...next];selectedProjectPaths=[];}
	const stepNames=['Scan','Global Context','Projects & Routing','Project Context','Review'];

	onMount(async()=>{
		if(!workspace.loaded)await workspace.load();
		const requested=new URLSearchParams(window.location.search).get('workspace')||'';
		targetWorkspaceId=requested||workspace.currentId||'';
		if(targetWorkspaceId&&workspace.currentId!==targetWorkspaceId&&workspace.workspaces.some((item)=>item.id===targetWorkspaceId))workspace.select(targetWorkspaceId);
		await loadSaved();
	});
</script>

<svelte:head><title>Knowledge Setup · OrbitFS</title></svelte:head>
<div class="mx-auto max-w-7xl space-y-4 p-3 sm:p-4 md:p-6">
	<div class="flex flex-wrap items-start justify-between gap-3">
		<div><h1 class="flex items-center gap-2 text-xl font-semibold"><BrainCircuit class="size-5"/>Workspace Knowledge Setup</h1><p class="text-sm text-muted-foreground">Set what matters globally, define projects, and tell OrbitFS how workspace knowledge should be loaded and routed.</p></div>
		<div class="flex gap-2"><Button variant="outline" onclick={()=>goto(`/workspaces?workspace=${encodeURIComponent(currentWorkspaceId())}`)}>Back to Workspace Manager</Button>{#if started}<Button variant="outline" onclick={reset}><RotateCcw class="size-4"/>Start over</Button>{/if}</div>
	</div>
	<Card><CardContent class="flex flex-wrap items-center justify-between gap-3 p-3"><div><div class="text-sm font-medium">{workspace.current?.name||'Current workspace'}</div><div class="text-xs text-muted-foreground">Stored in Supabase as Base Panel workspace architecture. Selected files are registered with the Library automatically.</div></div><div class="flex gap-1.5"><Badge variant="secondary"><CircleCheck class="mr-1 size-3"/>Library</Badge><Badge variant="secondary"><CircleCheck class="mr-1 size-3"/>Routing</Badge><Badge variant="secondary"><CircleCheck class="mr-1 size-3"/>Context</Badge></div></CardContent></Card>
	{#if error}<div class="rounded-md border border-destructive/30 bg-destructive/10 p-3 text-sm text-destructive">{error}</div>{/if}
	{#if notice}<div class="rounded-md border border-emerald-500/30 bg-emerald-500/10 p-3 text-sm text-emerald-500">{notice}</div>{/if}

	{#if !started}
		<Card class="border-dashed"><CardContent class="flex min-h-80 flex-col items-center justify-center gap-5 p-6 text-center"><div class="rounded-full border bg-muted/30 p-4"><FolderTree class="size-8 text-muted-foreground"/></div><div class="max-w-2xl"><h2 class="text-lg font-semibold">Set up this workspace</h2><p class="mt-2 text-sm text-muted-foreground">Scan the virtual workspace tree, choose global core/current content, define project roots and routing destinations, then save the architecture.</p></div><Button onclick={scan} disabled={scanning}><Search class="size-4"/>{scanning?'Scanning workspace…':'Scan workspace and begin'}</Button><p class="text-xs text-muted-foreground">Nothing changes until you save.</p></CardContent></Card>
	{:else}
		<div class="grid grid-cols-5 gap-1 rounded-lg border p-1 text-xs">{#each stepNames as name,index}<button class="rounded-md px-2 py-2 {step===index+1?'bg-accent font-medium':step>index+1?'text-success':'text-muted-foreground'}" onclick={()=>step=index+1}>{name}</button>{/each}</div>

		{#if step===1}
			<Card><CardHeader><CardTitle>Workspace scan</CardTitle><CardDescription>The tree is used as reference for setup; scanning does not change files.</CardDescription></CardHeader><CardContent class="grid gap-3 sm:grid-cols-2"><div class="rounded-md border p-4"><div class="text-2xl font-semibold">{flat.filter((item)=>item.type==='folder').length}</div><div class="text-xs text-muted-foreground">folders</div></div><div class="rounded-md border p-4"><div class="text-2xl font-semibold">{flat.filter((item)=>item.type==='file').length}</div><div class="text-xs text-muted-foreground">files</div></div></CardContent></Card><div class="flex justify-end"><Button onclick={()=>step=2}>Configure global context<ChevronRight class="size-4"/></Button></div>
		{:else if step===2}
			<div class="grid gap-4 lg:grid-cols-[minmax(320px,.9fr)_minmax(0,1.1fr)]"><Card><CardHeader><CardTitle>Global workspace context</CardTitle><CardDescription>Selecting a folder selects its current children too; each resulting row remains editable.</CardDescription></CardHeader><CardContent class="space-y-3"><label class="block space-y-1 text-xs"><span>Context group</span><select class="h-10 w-full rounded-md border bg-background px-3 text-sm" bind:value={globalGroup}><option>Global Core Files</option><option>Global Reference</option><option>Active Orders / Matters</option><option>Shared Reference</option><option>Custom</option></select></label><Input placeholder="Search folders and files…" bind:value={coreSearch}/><div class="max-h-[52vh] space-y-1 overflow-auto rounded-md border p-2">{#each flat.filter((item)=>!coreSearch.trim()||item.path.toLowerCase().includes(coreSearch.toLowerCase())).slice(0,250) as item}<label class="flex items-center gap-2 rounded px-2 py-1.5 text-xs hover:bg-muted/40"><input type="checkbox" checked={selectedCorePaths.includes(item.path)} onchange={(event)=>toggleCore(item.path,event.currentTarget.checked)}/>{#if item.type==='folder'}<Folder class="size-4 shrink-0"/>{:else}<FileText class="size-4 shrink-0"/>{/if}<span class="min-w-0 flex-1 truncate">{item.path}</span></label>{/each}</div><Button class="w-full" onclick={addSelectedCore} disabled={!selectedCorePaths.length}><Plus class="size-4"/>Add {selectedCorePaths.length||''} selected</Button></CardContent></Card><Card><CardHeader><CardTitle>Global rules</CardTitle><CardDescription>Role controls loading priority; state and protection preserve active/final/locked distinctions.</CardDescription></CardHeader><CardContent class="space-y-2">{#if !coreItems.filter((item)=>!item.projectId).length}<div class="rounded-md border border-dashed p-6 text-center text-sm text-muted-foreground">Nothing global configured yet.</div>{/if}{#each coreItems.filter((item)=>!item.projectId) as item}<div class="space-y-2 rounded-md border p-3"><div class="flex items-center justify-between gap-2"><div class="min-w-0"><strong class="block truncate text-sm">{item.path}</strong><span class="text-xs text-muted-foreground">{item.group} · {item.itemType}</span></div><Button size="icon" variant="ghost" onclick={()=>coreItems=coreItems.filter((entry)=>entry.id!==item.id)}><Trash2 class="size-4"/></Button></div><div class="grid gap-2 sm:grid-cols-3"><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.role}><option value="load-first">Load first</option><option value="always">Always</option><option value="active">Active/current</option><option value="relevant">Relevant</option><option value="requested">Requested</option><option value="search">Search only</option></select><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.state}><option value="active">Active</option><option value="final">Final</option><option value="superseded">Superseded</option><option value="archive">Archive</option></select><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.protection}><option value="editable">Editable</option><option value="permission">Permission controlled</option><option value="locked">Locked</option></select></div></div>{/each}</CardContent></Card></div><div class="flex justify-between"><Button variant="outline" onclick={()=>step=1}>Back</Button><Button onclick={()=>step=3}>Set up projects<ChevronRight class="size-4"/></Button></div>
		{:else if step===3}
			<div class="space-y-4"><Card><CardHeader><CardTitle>Projects / workspace areas</CardTitle><CardDescription>Attach a major workspace folder, then define category destinations inside it.</CardDescription></CardHeader><CardContent class="space-y-3"><div class="grid gap-3 md:grid-cols-[1fr_1fr_9rem_auto]"><Input placeholder="Project name" bind:value={newProject.name}/><select class="h-10 rounded-md border bg-background px-3 text-sm" bind:value={newProject.rootPath}><option value="">Choose project root folder</option>{#each flat.filter((item)=>item.type==='folder') as folder}<option value={folder.path}>{folder.path}</option>{/each}</select><select class="h-10 rounded-md border bg-background px-3 text-sm" bind:value={newProject.contextRole}><option value="active">Active project</option><option value="relevant">Load when relevant</option><option value="requested">Requested only</option></select><Button onclick={addProject} disabled={!newProject.name.trim()||!newProject.rootPath}><Plus class="size-4"/>Attach</Button></div></CardContent></Card>{#each projectSetups as project}<Card><CardHeader><div class="flex items-start justify-between gap-2"><div><CardTitle>{project.name}</CardTitle><CardDescription>{project.rootPath} · {project.contextRole}</CardDescription></div><Button size="icon" variant="ghost" onclick={()=>projectSetups=projectSetups.filter((entry)=>entry.id!==project.id)}><Trash2 class="size-4"/></Button></div></CardHeader><CardContent class="space-y-3"><div class="grid gap-2 md:grid-cols-[1fr_1.2fr_8rem_auto]"><Input placeholder="Content category" value={routeDrafts[project.id]?.label||''} oninput={(event)=>routeDrafts={...routeDrafts,[project.id]:{...(routeDrafts[project.id]||{destination:'',routing:'automatic'}),label:event.currentTarget.value}}}/><select class="h-10 rounded-md border bg-background px-3 text-sm" value={routeDrafts[project.id]?.destination||''} onchange={(event)=>routeDrafts={...routeDrafts,[project.id]:{...(routeDrafts[project.id]||{label:'',routing:'automatic'}),destination:event.currentTarget.value}}}><option value="">Destination folder</option>{#each flat.filter((item)=>item.type==='folder'&&(item.path===project.rootPath||item.path.startsWith(`${project.rootPath}/`))) as folder}<option value={folder.path}>{folder.path}</option>{/each}</select><select class="h-10 rounded-md border bg-background px-2 text-xs" value={routeDrafts[project.id]?.routing||'automatic'} onchange={(event)=>routeDrafts={...routeDrafts,[project.id]:{...(routeDrafts[project.id]||{label:'',destination:''}),routing:event.currentTarget.value as ProjectRoute['routing']}}}><option value="automatic">Automatic</option><option value="suggest">Suggest</option><option value="manual">Manual</option></select><Button onclick={()=>addProjectRoute(project.id)}>Add route</Button></div>{#each project.routes as route}<div class="grid gap-2 rounded-md border p-2 text-xs sm:grid-cols-[1fr_1.5fr_7rem_auto]"><strong>{route.label}</strong><span>{route.destination}</span><Badge variant="outline">{route.routing}</Badge><Button size="icon" variant="ghost" onclick={()=>projectSetups=projectSetups.map((entry)=>entry.id===project.id?{...entry,routes:entry.routes.filter((item)=>item.id!==route.id)}:entry)}><Trash2 class="size-4"/></Button></div>{/each}</CardContent></Card>{/each}</div><div class="flex justify-between"><Button variant="outline" onclick={()=>step=2}>Back</Button><Button onclick={()=>step=4} disabled={!projectSetups.length}>Project context<ChevronRight class="size-4"/></Button></div>
		{:else if step===4}
			<div class="grid gap-4 lg:grid-cols-[minmax(320px,.9fr)_minmax(0,1.1fr)]"><Card><CardHeader><CardTitle>Project context & overrides</CardTitle><CardDescription>Add project-specific files/folders without changing global rules.</CardDescription></CardHeader><CardContent class="space-y-3"><select class="h-10 w-full rounded-md border bg-background px-3 text-sm" bind:value={selectedProjectId} onchange={()=>selectedProjectPaths=[]}><option value="">Choose project</option>{#each projectSetups as project}<option value={project.id}>{project.name}</option>{/each}</select><label class="block space-y-1 text-xs"><span>Context group</span><select class="h-10 w-full rounded-md border bg-background px-3 text-sm" bind:value={projectGroup}><option>Active / Relevant Content</option><option>Project Core</option><option>Evidence / Source Material</option><option>Reference</option><option>Custom</option></select></label><Input placeholder="Search inside project…" bind:value={projectSearch}/>{#if selectedProjectId}{@const chosen=projectSetups.find((project)=>project.id===selectedProjectId)}<div class="max-h-[52vh] space-y-1 overflow-auto rounded-md border p-2">{#each flat.filter((item)=>chosen&&(item.path===chosen.rootPath||item.path.startsWith(`${chosen.rootPath}/`))&&(!projectSearch.trim()||item.path.toLowerCase().includes(projectSearch.toLowerCase()))).slice(0,250) as item}<label class="flex items-center gap-2 rounded px-2 py-1.5 text-xs hover:bg-muted/40"><input type="checkbox" checked={selectedProjectPaths.includes(item.path)} onchange={(event)=>toggleProjectPath(item.path,event.currentTarget.checked)}/>{#if item.type==='folder'}<Folder class="size-4"/>{:else}<FileText class="size-4"/>{/if}<span class="min-w-0 flex-1 truncate">{item.path}</span></label>{/each}</div><Button class="w-full" onclick={addSelectedProjectItems} disabled={!selectedProjectPaths.length}><Plus class="size-4"/>Add selected</Button>{/if}</CardContent></Card><Card><CardHeader><CardTitle>Project-specific rules</CardTitle></CardHeader><CardContent class="space-y-2">{#each coreItems.filter((item)=>item.projectId===selectedProjectId) as item}<div class="space-y-2 rounded-md border p-3"><div class="flex justify-between gap-2"><div><strong class="text-sm">{item.path}</strong><div class="text-xs text-muted-foreground">{item.group}</div></div><Button size="icon" variant="ghost" onclick={()=>coreItems=coreItems.filter((entry)=>entry.id!==item.id)}><Trash2 class="size-4"/></Button></div><div class="grid gap-2 sm:grid-cols-3"><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.role}><option value="load-first">Load first</option><option value="always">Always</option><option value="active">Active/current</option><option value="relevant">Relevant</option><option value="requested">Requested</option><option value="search">Search only</option></select><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.state}><option value="active">Active</option><option value="final">Final</option><option value="superseded">Superseded</option><option value="archive">Archive</option></select><select class="h-9 rounded-md border bg-background px-2 text-xs" bind:value={item.protection}><option value="editable">Editable</option><option value="permission">Permission controlled</option><option value="locked">Locked</option></select></div></div>{/each}</CardContent></Card></div><div class="flex justify-between"><Button variant="outline" onclick={()=>step=3}>Back</Button><Button onclick={()=>step=5}>Review<ChevronRight class="size-4"/></Button></div>
		{:else}
			<div class="grid gap-4 xl:grid-cols-[minmax(0,1.25fr)_minmax(300px,.75fr)]"><Card><CardHeader><CardTitle>Knowledge architecture</CardTitle><CardDescription>Global authority first, then project-specific context and routing.</CardDescription></CardHeader><CardContent class="space-y-4"><div><div class="mb-2 text-xs font-semibold uppercase text-muted-foreground">Global context</div>{#each coreItems.filter((item)=>!item.projectId) as item}<div class="mb-1 rounded-md border p-2 text-xs"><strong>{item.path}</strong><span class="text-muted-foreground"> · {item.group} · {item.role} · {item.state} · {item.protection}</span></div>{/each}</div><div><div class="mb-2 text-xs font-semibold uppercase text-muted-foreground">Projects</div>{#each projectSetups as project}<div class="mb-2 rounded-md border p-3"><div class="flex flex-wrap items-center gap-2"><strong>{project.name}</strong><Badge variant="outline">{project.contextRole}</Badge><span class="text-xs text-muted-foreground">{project.rootPath}</span></div><div class="mt-2 space-y-1">{#each project.routes as route}<div class="grid gap-1 rounded bg-muted/30 p-2 text-xs sm:grid-cols-[1fr_1.5fr_auto]"><strong>{route.label}</strong><span>{route.destination}</span><Badge variant="secondary">{route.routing}</Badge></div>{/each}</div><div class="mt-2 text-xs text-muted-foreground">{coreItems.filter((item)=>item.projectId===project.id).length} project context items</div></div>{/each}</div></CardContent></Card><Card><CardHeader><CardTitle>Save setup</CardTitle><CardDescription>The Base Panel stores this architecture in Supabase and registers selected files with Library.</CardDescription></CardHeader><CardContent class="space-y-3 text-xs"><p><strong>1. Global authority</strong> controls always/current context.</p><p><strong>2. Projects</strong> narrow relevant context and destinations.</p><p><strong>3. Routing</strong> provides explicit category destinations before learned/fallback behaviour.</p>{#if savedRevision}<p class="text-muted-foreground">Current saved revision: {savedRevision}</p>{/if}<Button class="w-full" onclick={saveArchitecture} disabled={saving}><Save class="size-4"/>{saving?'Saving…':savedRevision?'Save changes':'Finish setup'}</Button></CardContent></Card></div><div><Button variant="outline" onclick={()=>step=4}>Back</Button></div>
		{/if}
	{/if}
</div>
